head.script:
scwin.__triggerDbclick = function(id) {
    var node = WebSquare.wUnit.getDomById($p.id + id);
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.__isSorted = function(colID) {
    var td = WebSquare.wUnit.getJq(".grid_body_row").not(".w2grid_hidedRow").find('td[col_id=' + colID + ']');
    var arr = [];
    td.each(function() {
        arr.push(WebSquare.wUnit.getJq(this).text());
    });
    for (var i = 0; i < arr.length - 1; i++) {
        if (arr[i] > arr[i + 1]) {
            return false;
        }
    }
    return true;
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 2. 브라우저에서 3번째 컬럼 expression 을 더블클릭한다.
    //2. In the browser, double-click the third column expression. 
    WebSquare.wUnit.addCommand("set", "scwin.__triggerDbclick('grid1_column7')");
    WebSquare.wUnit.addCommand("pause", "1000");
    // verify step 3번째 컬럼 expression 이 Sort 된다.
    WebSquare.wUnit.addCommand("assert", "scwin.__isSorted('column8')", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Test step 3. 4번째 컬럼을 더블클릭한다.
    //3. Double-click the fourth column.
    WebSquare.wUnit.addCommand("set", "scwin.__triggerDbclick('grid1_column3')");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Verify step 3. 4번째 컬럼이 Sort 된다.
    WebSquare.wUnit.addCommand("assert", "scwin.__isSorted('column6')", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    grid1.setData([
        1, 2, "", "aa",
        1, 2, "", "xx",
        1, 2, "", "bb",
        1, 2, "", "nn",
        1, 2, "", "qq",
        1, 2, "", "zz"
    ]);
    //Function unitTest
    //Created By: Sang.do
    //Created By: 09-Feb-2018
    //end unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
